n=int(input("enter a number"))
for i in range(1,n+1):
    for s in range(n-i):
        print(" ",end="")
    for k in range(i):
        print("*",end=" ")
    print()
for m in range(n-1,0,-1):
    for s in range(n-m):
        print(" ",end="") 
    for p in range(m):
        print("*",end=" ")  
